import {AuditEventDomain,createAuditConsumerAdapter,sha256Text} from '../../../adapters/audit.js';
import {BackupRuntimeAdapter,BACKUP_COMMANDS} from '../../../adapters/backup-runtime.js';

const assert=(v    ,m='assertion failed')=>{if(!v)throw Error(m)};
const run=async(name       ,fn        ,out      )=>{try{await fn();out.push({name,status:'PASS'})}catch(e){out.push({name,status:'FAIL',error:String((e       )?.message||e)})}};
class FakeTransport{
  calls      =[];
  descriptor(){return {owner:'FakeTransport',availability:'AVAILABLE'}}
  async request(method       ,path       ,body    ){this.calls.push({method,path,body});if(path==='/v1/backup/package')return {ok:true,status:'PACKAGE_VERIFIED',packageId:'pkg-1',capturedAt:'2026-09-18T00:00:00Z',manifestSha256:'a'.repeat(64),snapshotSha256:'b'.repeat(64),schemaArtifactSha256:'c'.repeat(64),migrations:[{version:1,name:'schema-v1',checksum:'d'.repeat(64)}],readbackSummary:{documentCount:1},liveRestored:false,activationState:'NOT_REQUESTED'};if(path==='/v1/backup/drill')return {ok:true,status:'STAGED_AND_VERIFIED',drillId:'drill-1',packageId:body.packageId,target:{isolated:true,trueEmptyBeforeRestore:true},liveRestored:false,activationState:'NOT_REQUESTED'};if(path==='/v1/backup/activation-request')return {ok:true,status:'AUTHORITY_PENDING',requestId:'act-1',drillId:body.drillId,packageId:'pkg-1',liveRestored:false,productionDatabaseMutated:false};return {ok:false,code:'UNKNOWN'};}
}

export async function runS18DomainTests(){const t      =[];
 await run('audit.sha256-portable-known-vector',()=>assert(sha256Text('abc')==='ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad'),t);
 await run('audit.hash-chain-valid-and-not-encryption',()=>{const d=new AuditEventDomain({seed:false,clock:()=> '2026-09-18T00:00:00Z'});d.append({action:'ONE',target:'x'});d.append({action:'TWO',target:'y'});const v=d.verify();assert(v.status==='VALID_CHAIN'&&v.encryptionClaim===false&&v.hashAlgorithm==='SHA-256');},t);
 await run('audit.tamper-yields-first-invalid-sequence',()=>{const d=new AuditEventDomain({seed:false,clock:()=> '2026-09-18T00:00:00Z'});d.append({action:'ONE'});d.append({action:'TWO'});const rows=d.rows();rows[1].action='TAMPERED';const v=d.verifyObserved(rows);assert(v.status==='INVALID_CHAIN'&&v.firstInvalidSequence===2);},t);
 await run('audit.search-does-not-mutate-event-count-or-hash',()=>{const d=new AuditEventDomain({seed:false,clock:()=> '2026-09-18T00:00:00Z'});const e=d.append({action:'SEARCHABLE'}),before=d.truth().eventCount,r=d.search({query:'searchable'}),after=d.truth().eventCount;assert(r.ok&&r.mutatedAuditEventCount===0&&before===after&&d.rows()[0].recordHash===e.recordHash);},t);
 await run('audit.annotation-separate-and-record-hash-unchanged',()=>{const d=new AuditEventDomain({seed:false,clock:()=> '2026-09-18T00:00:00Z'});const e=d.append({action:'NOTE_TARGET'}),r=d.annotate({eventId:'1',note:'operator note'});assert(r.ok&&r.separateFromAuditEvent&&r.auditRecordHashUnchanged&&d.rows()[0].recordHash===e.recordHash&&d.truth().annotationCount===1);},t);
 await run('audit.provider-is-auditevent-domain-not-command-receipts',()=>{const a=createAuditConsumerAdapter();const p=a.provider.descriptor(),view=a.refresh();assert(p.authorityRef==='W05AuditDomain.events'&&p.domainKind==='cep-audit-events'&&view.entries.every((e    )=>e.kind==='AUDIT_EVENT')&&a.truth().commandReceiptsAreAuditTruth===false);},t);
 await run('backup.plan-preview-stage-perform-zero-provider-writes',async()=>{const transport=new FakeTransport(),a=new BackupRuntimeAdapter({transport,clock:()=> '2026-09-18T00:00:00Z'});await a.createPackage();const count=transport.calls.length;const p=a.plan(),v=a.preview(),s=a.stage();assert(p.ok&&v.ok&&s.ok&&transport.calls.length===count&&p.restoreWritesPerformed===false&&s.productionDatabaseMutated===false);},t);
 await run('backup.drill-requires-stage',async()=>{const transport=new FakeTransport(),a=new BackupRuntimeAdapter({transport});await a.createPackage();const r=await a.drill();assert(!r.ok&&r.code==='STAGED_PLAN_REQUIRED'&&!transport.calls.some(c=>c.path==='/v1/backup/drill'));},t);
 await run('backup.drill-isolated-and-not-live-restored',async()=>{const transport=new FakeTransport(),a=new BackupRuntimeAdapter({transport});await a.createPackage();a.plan();a.preview();a.stage();const r=await a.drill(),truth=a.truth();assert(r.ok&&r.status==='STAGED_AND_VERIFIED'&&r.target.isolated&&r.target.trueEmptyBeforeRestore&&r.liveRestored===false&&truth.stagedVerifiedIsLiveRestored===false);},t);
 await run('backup.activation-request-is-authority-pending-not-restore',async()=>{const transport=new FakeTransport(),a=new BackupRuntimeAdapter({transport});await a.createPackage();a.plan();a.preview();a.stage();await a.drill();const r=await a.requestActivation(),truth=a.truth();assert(r.ok&&r.status==='AUTHORITY_PENDING'&&r.liveRestored===false&&r.productionDatabaseMutated===false&&truth.activationAuthority==='AUTHORITY_PENDING');},t);
 await run('backup.no-persistence-owner-mutation',()=>{const a=new BackupRuntimeAdapter({transport:new FakeTransport()});const d=a.descriptor(),truth=a.truth();assert(d.persistenceOwnerMutation===false&&truth.persistenceOwnerMutated===false&&d.capabilityOwner==='BackupRestoreCapability');},t);
 await run('backup.durable-failure-gap-remains-truthful',()=>{const a=new BackupRuntimeAdapter({transport:new FakeTransport()});assert(a.truth().durableFailureCompensationHistory==='UNAVAILABLE_LOCKED_PROVIDER_SEAM');},t);
 await run('backup.profile-command-identities-preserved',()=>assert(JSON.stringify(BACKUP_COMMANDS)===JSON.stringify(['backup.plan','backup.preview','backup.stage','backup.drill','backup.activationRequest'])),t);
 return t;
}
if(import.meta.url===new URL(process.argv[1],'file:').href){const tests=await runS18DomainTests(),pass=tests.filter(x=>x.status==='PASS').length,fail=tests.filter(x=>x.status==='FAIL').length;console.log(JSON.stringify({lane:'S18_W05_BACKUP_AUDIT',pass,fail,tests},null,2));if(fail)process.exitCode=1;}
